function collides(x,z){
  for(const c of colliders){const nx=Math.max(c.x-c.w/2,Math.min(x,c.x+c.w/2)),nz=Math.max(c.z-c.d/2,Math.min(z,c.z+c.d/2));if((x-nx)**2+(z-nz)**2<.46**2)return true;}
