231: function startGame(){state.started=true;state.paused=false;state.over=false;ui.startScreen.classList.add('hidden');ui.pauseScreen.classList.remove('visible');canvas.focus();if(innerWidth>800)canvas.requestPointerLock?.();updateHUD();}
232: function nextRound(){state.round++;document.querySelector('#round-num').textContent=String(state.round).padStart(2,'0');state.hp=Math.min(100,state.hp+35);state.ammo=30;state.reserve+=60;state.grenades=1;state.won=false;state.secureTime=0;state.securing=false;state.reloading=false;ui.objectiveComplete.classList.remove('visible');ui.objectiveTitle.textContent='SECURE THE SITE';ui.objectiveCopy.textContent='Clear hostiles, then secure the uplink.';ui.objectiveBar.style.width='0%';const spawnList=enemySpawns.slice();for(let i=5;i<5+Math.min(state.round,4);i++){const angle=i*2.4;spawnList.push([Math.sin(angle)*7,-31-Math.cos(angle)*7]);}for(const e of enemies)scene.remove(e.root);enemies.length=0;spawnList.forEach((p,i)=>makeEnemy(i,p));player.position.set(0,0,13);state.yaw=0;updateHUD();addToast(`ROUND ${String(state.round).padStart(2,'0')} // HOSTILES INBOUND`);}
