235: window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='KeyR')reload();if(e.code==='KeyQ')throwGrenade();if(e.code==='KeyE')state.securing=true;if(e.code==='Space'&&state.started&&!state.paused&&!state.over&&!state.won){state.roll=.9;state.invulnerable=.6;}if(e.code==='Escape'&&state.started&&!state.over&&!state.won){state.paused=true;ui.pauseScreen.classList.add('visible');state.firing=false;document.exitPointerLock?.();}});
236: window.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='KeyE')state.securing=false;});
